    const recordedLogs = captureLogs();
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'create_booking',
        description: 'Create a booking',
        inputSchema: {
          type: 'object',
          properties: {
            seats: {type: 'number'},
            cabin: {type: 'string', enum: ['economy', 'business']},
            passenger: {
              type: 'object',
              properties: {passport: {type: 'string'}},
              required: ['passport'],
            },
          },
          required: ['seats', 'cabin', 'passenger'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'booked';
      }
    );

    const response = await registry.execute('create_booking', {
      seats: '42',
      cabin: 'secret-first-class',
      passenger: {},
    });
    const rootResponse = await registry.execute('create_booking', null as unknown as Record<string, unknown>);

    expect({
      executorCalls,
      mentionsSeatsNumber: response.result.includes('seats') && response.result.includes('number'),
      mentionsCabinEnum: response.result.includes('cabin') && response.result.includes('economy'),
      mentionsNestedPassport: response.result.includes('passenger.passport') && /required/i.test(response.result),
      mentionsRootInput: rootResponse.result.includes('input') && rootResponse.result.includes('object'),
      leaksValueInResult: response.result.includes('secret-first-class') || response.result.includes('42'),
      leaksValueInLogs: recordedLogs.some(line => line.includes('secret-first-class') || line.includes('42')),
    }).toEqual({
      executorCalls: 0,
      mentionsSeatsNumber: true,
      mentionsCabinEnum: true,
      mentionsNestedPassport: true,
      mentionsRootInput: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });

  it('passes valid input with undeclared extra properties through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather_with_defaults',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const response = await registry.execute('weather_with_defaults', {
      location: 'Berlin',
      extraTag: 123,
    });

    expect({response, receivedInputs}).toEqual({
      response: {result: 'ok'},
      receivedInputs: [{location: 'Berlin', extraTag: 123}],
    });
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    let errorMessage = '';
    try {
      await registry.execute('ghost_tool', {});
    } catch (error) {
      errorMessage = error instanceof Error ? error.message : String(error);
    }

    expect(errorMessage).toBe('Unknown tool: ghost_tool');
  });
});

